create extension if not exists pgcrypto;
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, role text not null default 'member' check(role in ('member','admin')), created_at timestamptz not null default now());
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.profiles where id=auth.uid() and role='admin')$$;
revoke all on function public.is_admin() from public; grant execute on function public.is_admin() to anon,authenticated;
create table public.gallery_items (id uuid primary key default gen_random_uuid(),title text not null check(length(title)<=160),description text not null default '' check(length(description)<=2000),image_path text not null unique,event_date date,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by uuid references auth.users(id));
create table public.members (id uuid primary key default gen_random_uuid(),name text not null check(length(name)<=120),designation text not null check(designation in ('President','Secretary','Treasurer','Executive Member','Volunteer','Advisor')),photo_path text,bio text not null default '' check(length(bio)<=2000),display_order integer not null default 0,active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.contact_messages (id uuid primary key default gen_random_uuid(),name text not null check(length(name)<=120),email text not null check(length(email)<=254),mobile text check(length(mobile)<=30),subject text not null check(length(subject)<=160),message text not null check(length(message)<=2000),created_at timestamptz not null default now());
create table public.donations (id uuid primary key default gen_random_uuid(),donor_name text not null,donor_email text not null,donor_mobile text,amount integer not null check(amount>=10000),currency text not null default 'INR',razorpay_order_id text unique,razorpay_payment_id text unique,status text not null default 'created' check(status in ('created','paid','failed','cancelled')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index gallery_event_idx on public.gallery_items(event_date desc); create index member_active_order_idx on public.members(active,display_order); create index donation_status_idx on public.donations(status);
alter table public.gallery_items enable row level security; alter table public.members enable row level security; alter table public.contact_messages enable row level security; alter table public.donations enable row level security; alter table public.profiles enable row level security;
create policy "public gallery read" on public.gallery_items for select using(true); create policy "admin gallery write" on public.gallery_items for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy "public active members" on public.members for select using(active or public.is_admin()); create policy "admin members write" on public.members for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy "public contact submit" on public.contact_messages for insert to anon,authenticated with check(length(message)<=2000); create policy "admin contacts read" on public.contact_messages for select to authenticated using(public.is_admin());
create policy "admin donation read" on public.donations for select to authenticated using(public.is_admin()); create policy "users view own profile" on public.profiles for select to authenticated using(id=auth.uid());
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values ('gallery','gallery',true,5242880,array['image/jpeg','image/png','image/webp','image/avif']),('members','members',true,5242880,array['image/jpeg','image/png','image/webp','image/avif']) on conflict(id) do update set public=true,file_size_limit=5242880;
create policy "public image read" on storage.objects for select using(bucket_id in ('gallery','members')); create policy "admins manage images" on storage.objects for all to authenticated using(bucket_id in ('gallery','members') and public.is_admin()) with check(bucket_id in ('gallery','members') and public.is_admin());
